const late = document.getElementById('late');
setTimeout(() => { late.hidden = false; }, 500);
const feed = document.getElementById('feed');
const counter = document.getElementById('counter');
const toggle = document.getElementById('toggle');
let updates = 0;
let reordering = true;
toggle.addEventListener('click', () => {
  reordering = !reordering;
  toggle.setAttribute('aria-pressed', String(!reordering));
  toggle.textContent = reordering ? 'Pause reordering' : 'Resume reordering';
});
setInterval(() => {
  if (!reordering) return;
  const first = feed.firstElementChild;
  feed.appendChild(first);
  updates += 1;
  counter.textContent = updates + ' updates';
}, 1000);

